"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5381],{15776:e=>{e.exports=JSON.parse('{"functions":[{"name":"build","desc":"Builds a frozen cycle of reward indices whose counts are proportional to\\n`weights`. The cycle has at least 100 entries (more when the rarest weight is\\nunder 1% of the total), its counts are allocated by largest remainder, its\\nentries are interleaved as evenly as possible, and it starts at the first\\noccurrence of the rarest reward. A single weight returns `{ 1 }`.","params":[{"name":"weights","desc":"Positive weights, one per reward. Errors if empty or if any weight is not positive.","lua_type":"{ number }"}],"returns":[{"desc":"A frozen array of indices into `weights`.","lua_type":"{ number }"}],"function_type":"static","source":{"line":33,"path":"src/FixedRewardSequence.luau"}}],"properties":[],"types":[],"name":"FixedRewardSequence","desc":"Builds deterministic reward sequences. Instead of rolling a random reward each\\ntime, step through a pre-built cycle whose reward frequencies match the weights\\nexactly and whose rewards are spread out as evenly as possible.\\n\\n```lua\\nlocal sequence = FixedRewardSequence.build({ 70, 25, 5 })\\n\\nlocal step = 0\\nlocal function nextReward(): number\\n\\tstep = step % #sequence + 1\\n\\treturn sequence[step] -- 1, 2 or 3\\nend\\n```","source":{"line":19,"path":"src/FixedRewardSequence.luau"}}')}}]);